    rows.append((abs(s-TARGET),s,exp,aliases,status,len(files),files))
for r in sorted(rows)[:50]:
    diff,s,exp,aliases,status,n,files=r
    print(diff,s,exp,status,n,aliases)
    print(' ', files[:5])
